using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PurifyCorruptCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PurifyCorruptCustomDescription", order = 0)]
public class PurifyCorruptCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string text = "";
		text = ((!(amountModified == "-4")) ? GetRawLocalizedDescription(battleAction) : base.localizationManager.GetLocalizedString(battleAction.BaseBattleActionData.ActionIDDescription + "FutureLatinLanguages"));
		if (amountModified == "-3" || amountModified == "-4")
		{
			text = ReplacePreposition(text);
		}
		else if (amountModified == EffectsValues.NO_VALUE_STRING || amountModified == "-1")
		{
			amountModified = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedX();
		}
		else if (amountModified == "-5")
		{
			amountModified = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedY();
		}
		if (amountModified != "-3" && amountModified != "-4")
		{
			text = Smart.Format(text, amountModified);
		}
		return Smart.Format(GetTargetCorruptPurifyLocalized(battleAction), text);
	}

	private string ReplacePreposition(string text)
	{
		if (LanguagesIndexes.CurrentLanguageIndex == 1 || LanguagesIndexes.CurrentLanguageIndex == 9)
		{
			return text.Replace(" {0} de", "");
		}
		if (LanguagesIndexes.CurrentLanguageIndex == 4)
		{
			return text.Replace(" x\u00a0{0}", "");
		}
		if (LanguagesIndexes.IsCurrentLanguageRussian())
		{
			return text.Replace(" ×{0}", "").Replace("\u00a0×{0}", "");
		}
		return text.Replace(" {0}", "").Replace("{0}", "");
	}

	public string GetTargetCorruptPurifyLocalized(BattleAction battleAction)
	{
		string text = "";
		text = ((!battleAction.TargetData) ? "AnyCP" : battleAction.TargetData.TargetCorruptPurifyID);
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(text);
	}
}
